<?php
session_start();include('check-login.php');include('dbstring.php');
if(!(isset($_SESSION['ACCESSLEVEL'],$_SESSION['SYSTEMTYPE'])&&$_SESSION['ACCESSLEVEL']==='user'&&$_SESSION['SYSTEMTYPE']==='Student')){header('Location:index.php');exit();}$uid=mysqli_real_escape_string($con,$_SESSION['USERID']);$rows=array();$r=mysqli_query($con,"SELECT bi.billid,itm.itemname,bi.cost,bi.cost-COALESCE(SUM(pm.payment),0) balance FROM tblbilling bi INNER JOIN tblitemprice ip ON ip.itempriceid=bi.itempriceid INNER JOIN tblitem itm ON itm.itemid=ip.itemid LEFT JOIN tblpayment pm ON pm.billid=bi.billid AND pm.status='active' WHERE bi.userid='$uid' AND bi.status='active' GROUP BY bi.billid,itm.itemname,bi.cost HAVING balance>0.009");if($r)while($x=mysqli_fetch_assoc($r))$rows[]=$x;function sfp($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
?>
<!doctype html><html><head><?php include('links.php');?><title>Pay School Fees</title><style>body{background:#f4f8fb;font-family:Arial;color:#17314b}.sfp{max-width:850px;margin:25px auto;background:#fff;padding:24px;border-radius:16px}.bill{padding:13px;border:1px solid #dce6ee;border-radius:10px;margin:9px 0;display:grid;grid-template-columns:24px 1fr 180px;gap:12px;align-items:center}.bill input[type=number]{width:100%;padding:9px;box-sizing:border-box;background:#fff;color:#102a43;border:1px solid #7893aa;border-radius:7px}.pay{background:#087443;color:#fff;border:0;border-radius:8px;padding:12px 16px;font-weight:bold;margin-top:15px}@media(max-width:600px){.bill{grid-template-columns:24px 1fr}.bill div:last-child{grid-column:2}}</style></head><body><main class="sfp"><h1>Pay School Fees</h1><p>Choose a bill, then enter any amount up to its outstanding balance.</p><form method="post" action="student-fee-paystack-init.php"><?php foreach($rows as $x){?><label class="bill"><input type="checkbox" name="billids[]" value="<?php echo sfp($x['billid']);?>"><span><strong><?php echo sfp($x['itemname']);?></strong><br><small>Outstanding balance: GHS <?php echo number_format($x['balance'],2);?></small></span><div><label>Pay now (GHS)</label><input type="number" name="amounts[<?php echo sfp($x['billid']);?>]" min="0.01" max="<?php echo sfp($x['balance']);?>" step="0.01" value="<?php echo sfp($x['balance']);?>"></div></label><?php }?><?php if(empty($rows)){?><p>You have no outstanding active bills.</p><?php }else{?><button class="pay">Continue to Paystack</button><?php }?></form></main></body></html>
